from collections import deque


class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        self._customers: dict[str, bool] = {}
        # Separate queues for each priority to maintain FIFO order within the same priority
        self._queues: dict[str, deque[int]] = {
            priority: deque() for priority in self.PRIORITIES
        }
        # Ticket metadata storage: ticket_id -> dict
        self._tickets: dict[int, dict] = {}
        self._next_id: int = 1

    def add_customer(self, name: str, vip: bool = False) -> None:
        self._customers[name] = vip

    def open_ticket(self, customer: str, title: str, priority: str = "normal") -> int:
        """Open a ticket; returns its id."""
        if not title:
            raise ValueError("Ticket title cannot be empty.")
        if priority not in self.PRIORITIES:
            raise ValueError(f"Invalid priority '{priority}'. Must be one of {self.PRIORITIES}.")

        ticket_id = self._next_id
        self._next_id += 1

        self._tickets[ticket_id] = {
            "customer": customer,
            "title": title,
            "priority": priority,
            "status": "open",  # "open", "in_progress", or "closed"
        }
        self._queues[priority].append(ticket_id)
        return ticket_id

    def next_ticket(self) -> int | None:
        """Take the ticket that should be handled next out of the queue; None if the queue is empty."""
        for priority in reversed(self.PRIORITIES):
            if self._queues[priority]:
                ticket_id = self._queues[priority].popleft()
                self._tickets[ticket_id]["status"] = "in_progress"
                return ticket_id
        return None

    def close(self, ticket_id: int) -> None:
        if ticket_id not in self._tickets:
            raise KeyError(f"Ticket {ticket_id} does not exist.")

        ticket = self._tickets[ticket_id]
        if ticket["status"] == "open":
            # Remove from queue if it was still queued
            self._queues[ticket["priority"]].remove(ticket_id)

        ticket["status"] = "closed"

    def reopen(self, ticket_id: int) -> None:
        """Put a ticket back into the queue."""
        if ticket_id not in self._tickets:
            raise KeyError(f"Ticket {ticket_id} does not exist.")

        ticket = self._tickets[ticket_id]
        if ticket["status"] == "closed":
            raise ValueError(f"Cannot reopen closed ticket {ticket_id}.")

        if ticket["status"] != "open":
            ticket["status"] = "open"
            self._queues[ticket["priority"]].append(ticket_id)
